package ma.lias.controller;
import ma.lias.entity.*; import ma.lias.repository.MessageRepository; import ma.lias.service.AuditService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/messages")
public class MessageController { private final MessageRepository repo; private final AuditService audit; public MessageController(MessageRepository repo, AuditService audit){this.repo=repo;this.audit=audit;} @GetMapping public List<Message> all(@RequestParam(required=false) Long eventId){return eventId==null?repo.findTop50ByOrderBySentAtDesc():repo.findByEventIdOrderBySentAtAsc(eventId);} @PostMapping public ResponseEntity<Message> create(@RequestBody Message body, org.springframework.security.core.Authentication auth){ if(auth!=null && auth.getPrincipal() instanceof User u) body.setSenderId(u.getId()); Message saved=repo.save(body); audit.log("CREATE","Message",saved.getId(),"Message"); return ResponseEntity.status(HttpStatus.CREATED).body(saved);} }
